/**
 * Fixture byte generators (story 12).
 *
 * Pure TypeScript so the same fixtures work in node unit tests, in workerd
 * integration tests (no Node `zlib`, no file system) and in the browser. The PNG
 * writer emits a genuinely decodable file using stored (uncompressed) deflate
 * blocks, which keeps the generator free of dependencies; the other formats
 * carry correct container signatures plus filler, which is all the sniffing and
 * size rules look at. Real decodable JPEG/GIF/WebP files for the e2e specs are
 * generated by `tests/fixtures/generate-images.mjs`.
 */

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(bytes: Uint8Array): number {
  let c = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function adler32(bytes: Uint8Array): number {
  let a = 1;
  let b = 0;
  for (let i = 0; i < bytes.length; i++) {
    a = (a + bytes[i]) % 65521;
    b = (b + a) % 65521;
  }
  return ((b << 16) | a) >>> 0;
}

function chunk(out: number[], type: string, data: Uint8Array): void {
  out.push(
    (data.length >>> 24) & 0xff,
    (data.length >>> 16) & 0xff,
    (data.length >>> 8) & 0xff,
    data.length & 0xff,
  );
  for (let i = 0; i < 4; i++) out.push(type.charCodeAt(i));
  for (let i = 0; i < data.length; i++) out.push(data[i]);
  const crcInput = new Uint8Array([...typeBytes(type), ...data]);
  const crc = crc32(crcInput);
  out.push((crc >>> 24) & 0xff, (crc >>> 16) & 0xff, (crc >>> 8) & 0xff, crc & 0xff);
}

function typeBytes(type: string): number[] {
  return [type.charCodeAt(0), type.charCodeAt(1), type.charCodeAt(2), type.charCodeAt(3)];
}

/** Deflate the data as stored (uncompressed) blocks, wrapped in a zlib stream. */
function zlibStored(data: Uint8Array): Uint8Array<ArrayBuffer> {
  const out: number[] = [0x78, 0x01]; // zlib header: deflate, 32K window, FCHECK
  let offset = 0;
  const MAX_BLOCK = 65535;
  if (data.length === 0) {
    out.push(0x01, 0x00, 0xff, 0xff, 0x00); // final empty stored block
  }
  while (offset < data.length) {
    const size = Math.min(MAX_BLOCK, data.length - offset);
    const isFinal = offset + size >= data.length;
    out.push(isFinal ? 0x01 : 0x00);
    out.push(size & 0xff, (size >>> 8) & 0xff);
    const nlen = ~size & 0xffff;
    out.push(nlen & 0xff, (nlen >>> 8) & 0xff);
    for (let i = 0; i < size; i++) out.push(data[offset + i]);
    offset += size;
  }
  const ad = adler32(data);
  out.push((ad >>> 24) & 0xff, (ad >>> 16) & 0xff, (ad >>> 8) & 0xff, ad & 0xff);
  return Uint8Array.from(out);
}

/**
 * A real, decodable RGB PNG of the requested size with a vertical gradient, so
 * `createImageBitmap`/`<img>` can measure it.
 */
export function pngBytes(
  width = 8,
  height = 8,
  from: readonly [number, number, number] = [0x4a, 0x90, 0xd9],
  to: readonly [number, number, number] = [0x26, 0x32, 0x38],
): Uint8Array<ArrayBuffer> {
  const rows: number[] = [];
  for (let y = 0; y < height; y++) {
    rows.push(0); // filter: none
    const t = height > 1 ? y / (height - 1) : 0;
    const r = Math.round(from[0] + (to[0] - from[0]) * t);
    const g = Math.round(from[1] + (to[1] - from[1]) * t);
    const b = Math.round(from[2] + (to[2] - from[2]) * t);
    for (let x = 0; x < width; x++) rows.push(r, g, b);
  }
  const raw = Uint8Array.from(rows);

  const ihdr = new Uint8Array(13);
  const write32 = (arr: Uint8Array, at: number, value: number) => {
    arr[at] = (value >>> 24) & 0xff;
    arr[at + 1] = (value >>> 16) & 0xff;
    arr[at + 2] = (value >>> 8) & 0xff;
    arr[at + 3] = value & 0xff;
  };
  write32(ihdr, 0, width);
  write32(ihdr, 4, height);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: truecolour RGB
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;

  const out: number[] = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  chunk(out, 'IHDR', ihdr);
  chunk(out, 'IDAT', zlibStored(raw));
  chunk(out, 'IEND', new Uint8Array(0));
  return Uint8Array.from(out);
}

/**
 * A JPEG: correct `FF D8 FF` signature plus a JFIF APP0 segment, padded to
 * `totalBytes` when asked (used for the 10 MB boundary tests).
 */
export function jpegBytes(totalBytes = 0): Uint8Array<ArrayBuffer> {
  const head = [
    0xff, 0xd8, 0xff, 0xe0, 0x00, 0x10,
    0x4a, 0x46, 0x49, 0x46, 0x00, // "JFIF\0"
    0x01, 0x01, 0x01, 0x00, 0x48, 0x00, 0x48, 0x00, 0x00,
  ];
  const total = Math.max(totalBytes, head.length + 2);
  const out = new Uint8Array(total);
  out.set(head, 0);
  for (let i = head.length; i < total - 2; i++) out[i] = 0x20;
  out[total - 2] = 0xff;
  out[total - 1] = 0xd9; // EOI
  return out;
}

/** A GIF with the requested version header plus filler. */
export function gifBytes(version: 'GIF87a' | 'GIF89a' = 'GIF89a', size = 64): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(Math.max(size, 13));
  for (let i = 0; i < version.length; i++) out[i] = version.charCodeAt(i);
  out[6] = 2; // logical screen width
  out[7] = 0;
  out[8] = 2; // height
  out[9] = 0;
  out[10] = 0x80; // global colour table, 2 entries
  out[12] = 0;
  return out;
}

/** A WebP: `RIFF` … `WEBP` plus filler. */
export function webpBytes(size = 64): Uint8Array<ArrayBuffer> {
  const total = Math.max(size, 20);
  const out = new Uint8Array(total);
  'RIFF'.split('').forEach((c, i) => (out[i] = c.charCodeAt(0)));
  const len = total - 8;
  out[4] = len & 0xff;
  out[5] = (len >>> 8) & 0xff;
  out[6] = (len >>> 16) & 0xff;
  out[7] = (len >>> 24) & 0xff;
  'WEBP'.split('').forEach((c, i) => (out[8 + i] = c.charCodeAt(0)));
  'VP8 '.split('').forEach((c, i) => (out[12 + i] = c.charCodeAt(0)));
  return out;
}

/** An SVG carrying a script — never acceptable, no matter the file name. */
export function svgBytes(): Uint8Array<ArrayBuffer> {
  return new TextEncoder().encode(
    '<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40">' +
      '<script>alert(1)</script><rect width="40" height="40" fill="#0af" /></svg>',
  );
}

/** A minimal PDF, used for the "renamed to .png" disguises. */
export function pdfBytes(): Uint8Array<ArrayBuffer> {
  return new TextEncoder().encode(
    '%PDF-1.4\n1 0 obj << /Type /Catalog >> endobj\ntrailer << /Root 1 0 R >>\n%%EOF\n',
  );
}

/** Deterministic pseudo-random bytes (a "corrupt" or unknown file). */
export function randomBytes(count: number, seed = 7): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(count);
  let state = seed >>> 0;
  for (let i = 0; i < count; i++) {
    state = (state * 1664525 + 1013904223) >>> 0;
    out[i] = (state >>> 24) & 0xff;
  }
  return out;
}

/** A PNG cut short after its header: correct signature, undecodable body. */
export function truncatedPngBytes(): Uint8Array<ArrayBuffer> {
  return pngBytes(8, 8).subarray(0, 24);
}
